const source_47 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"社区\";\nexport const order = 320;\n// Favicon: https://static.coolapk.com/images/apple-touch-icon-120x120.png\nexport const platform = {\n  name: \"酷安\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"kuan-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"kuan-favicon\\\"/></svg>\",\n};\nimport {\n  utils\n} from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"coolapk\",\n  \"name\": \"酷安 · 今日最热\",\n  \"home\": \"https://coolapk.com\"\n};\nexport class KuanHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const request_options = {\n        headers: this.app_headers()\n      };\n      request_options.headers = {\n        Referer: source.home,\n        ...request_options.headers\n      };\n      const fetched = await utils.request_json(ctx, \"https://api.coolapk.com/v6/page/dataList?url=%2Ffeed%2FstatList%3FcacheExpires%3D300%26statType%3Dday%26sortField%3Ddetailnum%26title%3D%E4%BB%8A%E6%97%A5%E7%83%AD%E9%97%A8&title=%E4%BB%8A%E6%97%A5%E7%83%AD%E9%97%A8&subTitle=&page=1\", request_options);\n      if (fetched.error) return fetched;\n      const data = fetched.data;\n      if (!data || typeof data !== 'object') return Result.Err('上游未返回数据对象', 'UPSTREAM_INVALID_RESPONSE');\n      if (data.need_force_login) return Result.Err('上游要求登录，请更新并授权 Cookie', 'UPSTREAM_AUTH_REQUIRED');\n      if (data.error || data.errors?.length || (typeof data.code === 'number' && data.code < 0) || (data.error_code !== undefined && data.error_code !== 0)) return Result.Err('上游拒绝请求，请检查账户权限或验证页面', 'UPSTREAM_INVALID_RESPONSE');\n      const list = utils.array_at(data, \"data\");\n      if (list.error) return list;\n      const rows = list.data;\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        if (!row.id) continue;\n        const id = utils.identity(row.id);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url(row.url, \"https://www.coolapk.com/\");\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = row.rank;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String(row.targetRow?.subTitle ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.editor_title || utils.plain_text(row.message).split('\\n')[0]),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n  md5_ascii(value) {\n    const bytes = [];\n    for (let i = 0; i < value.length; i++) bytes.push(value.charCodeAt(i));\n    const length = bytes.length;\n    bytes.push(128);\n    while (bytes.length % 64 !== 56) bytes.push(0);\n    for (let i = 0; i < 8; i++)\n      bytes.push(Math.floor((length * 8) / Math.pow(256, i)) & 255);\n    let state = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476];\n    const shifts = [\n      [7, 12, 17, 22],\n      [5, 9, 14, 20],\n      [4, 11, 16, 23],\n      [6, 10, 15, 21],\n    ];\n    for (let offset = 0; offset < bytes.length; offset += 64) {\n      const words = [];\n      for (let i = 0; i < 16; i++) {\n        const p = offset + i * 4;\n        words.push(\n          bytes[p] |\n          (bytes[p + 1] << 8) |\n          (bytes[p + 2] << 16) |\n          (bytes[p + 3] << 24),\n        );\n      }\n      let [a, b, c, d] = state;\n      for (let i = 0; i < 64; i++) {\n        let f, g;\n        if (i < 16) {\n          f = (b & c) | (~b & d);\n          g = i;\n        } else if (i < 32) {\n          f = (d & b) | (~d & c);\n          g = (5 * i + 1) % 16;\n        } else if (i < 48) {\n          f = b ^ c ^ d;\n          g = (3 * i + 5) % 16;\n        } else {\n          f = c ^ (b | ~d);\n          g = (7 * i) % 16;\n        }\n        const sum =\n          (a +\n            f +\n            Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) +\n            words[g]) |\n          0;\n        const shift = shifts[Math.floor(i / 16)][i % 4];\n        const next = (b + ((sum << shift) | (sum >>> (32 - shift)))) | 0;\n        a = d;\n        d = c;\n        c = b;\n        b = next;\n      }\n      state = state.map((v, i) => (v + [a, b, c, d][i]) | 0);\n    }\n    return state\n      .map((v) => [0, 8, 16, 24]\n        .map((s) => ((v >>> s) & 255).toString(16).padStart(2, \"0\"))\n        .join(\"\"),\n      )\n      .join(\"\");\n  }\n  base64_ascii(value) {\n    const alphabet = \"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/\";\n    let encoded = \"\";\n    for (let i = 0; i < value.length; i += 3) {\n      const chunk = (value.charCodeAt(i) << 16) | ((value.charCodeAt(i + 1) || 0) << 8) | (value.charCodeAt(i + 2) || 0);\n      encoded += alphabet[(chunk >>> 18) & 63] + alphabet[(chunk >>> 12) & 63] + (i + 1 < value.length ? alphabet[(chunk >>> 6) & 63] : \"=\") + (i + 2 < value.length ? alphabet[chunk & 63] : \"=\");\n    }\n    return encoded;\n  }\n  app_headers() {\n    const device = [10, 6, 6, 6, 14].map(length => Math.random().toString(36).substring(2, length)).join(\"-\");\n    const now = Math.round(Date.now() / 1000);\n    const seed = \"token://com.coolapk.market/c67ef5943784d09750dcfbb31020f0ab?\" + this.md5_ascii(String(now)) + \"$\" + device + \"&com.coolapk.market\";\n    return {\n      \"X-Requested-With\": \"XMLHttpRequest\",\n      \"X-App-Id\": \"com.coolapk.market\",\n      \"X-App-Token\": this.md5_ascii(this.base64_ascii(seed)) + device + \"0x\" + now.toString(16),\n      \"X-Sdk-Int\": \"29\",\n      \"X-Sdk-Locale\": \"zh-CN\",\n      \"X-App-Version\": \"11.0\",\n      \"X-Api-Version\": \"11\",\n      \"X-App-Code\": \"2101202\",\n      \"User-Agent\": \"Dalvik/2.1.0 (Linux; U; Android 10; Redmi K30 5G MIUI/V12.0.3.0.QGICMXM) (#Build; Redmi; Redmi K30 5G; QKQ1.191222.002 test-keys; 10) +CoolMarket/11.0-2101202\"\n    };\n  }\n}\nconst script = new KuanHotRank();\nexport const route = {\n  \"name\": \"酷安 · 今日最热\",\n  \"path\": \"/kuan\",\n  \"url\": \"coolapk.com\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/kuan\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_48 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"科技\";\nexport const order = 620;\n// Favicon: https://www.google.com/s2/favicons?domain=lobste.rs&sz=32\nexport const platform = { name: \"Lobsters\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"lobsters-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"lobsters-favicon\\\"/></svg>\" };\nexport const tags = [\"社区\", \"编程\", \"英语\"];\n\nexport class LobstersHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const fetched = await utils.request_json(ctx, \"https://lobste.rs/hottest.json\");\n      if (fetched.error) return fetched;\n      const list = utils.array_at(fetched.data);\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"Lobsters 热门列表为空\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        const id = row?.short_id;\n        if (typeof id !== \"string\" || !/^[a-z0-9]+$/i.test(id)) return Result.Err(\"Lobsters 缺少有效帖子 ID\", \"UPSTREAM_INVALID_RESPONSE\");\n        if (seen.has(id)) continue;\n        seen.add(id);\n        entries.push({ id: \"lobsters:\" + id, title: utils.plain_text(row.title), link: \"https://lobste.rs/s/\" + id,\n          rank: null, pinned: false,\n          heat: { value: Number.isFinite(row.score) && row.score >= 0 ? row.score : null, unit: \"得分\", text: String(row.score ?? \"\") } });\n      }\n      return Result.Ok({ category, title: \"Lobsters · 热门讨论\", link: \"https://lobste.rs/\", entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new LobstersHotRank();\nexport const route = {\n  name: \"Lobsters · 热门讨论\", path: \"/lobsters/hot\", url: \"lobste.rs\",\n  maintainers: [\"findrss\"], example: \"/lobsters/hot\", parameters: {},\n  description: \"读取官方 hottest JSON 第一页，链接到讨论页，保留得分和原顺序；无显式排名，rank 为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_49 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"社交\";\nexport const order = 650;\n// Favicon: https://www.google.com/s2/favicons?domain=mastodon.social&sz=32\nexport const platform = { name: \"Mastodon\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"mastodon-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"mastodon-favicon\\\"/></svg>\" };\nexport const tags = [\"社媒\", \"新闻\", \"英语\"];\n\nconst types = { links: \"热门链接\", tags: \"热门话题\", statuses: \"热门动态\" };\n\nexport class MastodonHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const type = ctx.params.type || \"links\";\n      if (!Object.hasOwn(types, type)) return Result.Err(\"type 支持 links（默认）、tags、statuses\", \"INVALID_PARAMETER\");\n      const home = \"https://mastodon.social\";\n      const fetched = await utils.request_json(ctx, home + \"/api/v1/trends/\" + type + \"?limit=20\");\n      if (fetched.error) return fetched;\n      const list = utils.array_at(fetched.data);\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"Mastodon 实例未返回趋势列表\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        const link = utils.absolute_url(row?.url, home);\n        if (link.error) return link;\n        if (!link.data) return Result.Err(\"Mastodon 趋势条目缺少链接\", \"UPSTREAM_INVALID_RESPONSE\");\n        const id = utils.identity(type === \"statuses\" ? row.id : link.data);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const text = String((type === \"statuses\" ? row.favourites_count : row.history?.[0]?.uses) ?? \"\");\n        const thumbnail = utils.absolute_url(type === \"links\" ? row.image : type === \"statuses\" ? row.media_attachments?.[0]?.preview_url : \"\", home);\n        if (thumbnail.error) return thumbnail;\n        const title = type === \"links\" ? utils.plain_text(row.title) : type === \"tags\" ? \"#\" + (row.name || \"\")\n          : (utils.plain_text(row.spoiler_text || row.content) || utils.plain_text(row.account?.display_name) || utils.plain_text(row.account?.acct)).slice(0, 200);\n        if (type === \"tags\" && !row.name) return Result.Err(\"Mastodon 话题缺少名称\", \"UPSTREAM_INVALID_RESPONSE\");\n        entries.push({ id: \"mastodon.social:\" + type + \":\" + id.data, title, link: link.data,\n          ...(thumbnail.data ? { thumbnail: thumbnail.data } : {}), rank: null, pinned: false,\n          heat: { value: text === \"\" ? null : Number(text), unit: type === \"statuses\" ? \"点赞\" : \"当日分享次数\", text } });\n      }\n      return Result.Ok({ category, title: \"Mastodon · \" + types[type],\n        link: home + \"/explore\" + (type === \"statuses\" ? \"\" : \"/\" + type), entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new MastodonHotRank();\nexport const route = {\n  name: \"Mastodon · 社媒趋势\", path: \"/mastodon/trending/:type?\", url: \"mastodon.social\",\n  maintainers: [\"findrss\"], example: \"/mastodon/trending/links\", parameters: { type: \"links 热门链接（默认）、tags 话题、statuses 动态\" },\n  description: \"固定读取 mastodon.social 公开趋势，范围为该实例可见及审核的内容，并非全网排名；保留顺序，rank 为 null。链接/话题热度为 history 首日 uses，动态为点赞数。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_50 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"财经\";\nexport const order = 330;\n// Favicon: https://mktnews.net/favicon.ico\nexport const platform = {\n  name: \"MKTNews\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"mktnews-flash-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"mktnews-flash-favicon\\\"/></svg>\",\n};\nimport { utils } from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"mktnews-flash\",\n  \"name\": \"MKTNews · 快讯\",\n  \"home\": \"https://mktnews.net\"\n};\nexport class MktnewsFlashHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const request_options = {\n        headers: {\n          Origin: \"https://mktnews.net\",\n          Referer: \"https://mktnews.net/\"\n        }\n      };\n      request_options.headers = {\n        Referer: source.home,\n        ...request_options.headers\n      };\n      const fetched = await utils.request_json(ctx, \"https://api.mktnews.net/api/flash?type=0&limit=50\", request_options);\n      if (fetched.error) return fetched;\n      const data = fetched.data;\n      if (!data || typeof data !== 'object') return Result.Err('上游未返回数据对象', 'UPSTREAM_INVALID_RESPONSE');\n      if (data.need_force_login) return Result.Err('上游要求登录，请更新并授权 Cookie', 'UPSTREAM_AUTH_REQUIRED');\n      if (data.error || data.errors?.length || (typeof data.code === 'number' && data.code < 0) || (data.error_code !== undefined && data.error_code !== 0)) return Result.Err('上游拒绝请求，请检查账户权限或验证页面', 'UPSTREAM_INVALID_RESPONSE');\n      const list = utils.array_at(data, \"data\");\n      if (list.error) return list;\n      const rows = list.data;\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        const id = utils.identity(row.id);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url('https://mktnews.net/flashDetail.html?id=' + encodeURIComponent(id.data), source.home);\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = null;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String('' ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.data?.title || utils.plain_text(row.data?.content).match(/【([^】]+)】/)?.[1] || row.data?.content),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n}\nconst script = new MktnewsFlashHotRank();\nexport const route = {\n  \"name\": \"MKTNews · 快讯\",\n  \"path\": \"/mktnews/flash\",\n  \"url\": \"mktnews.net\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/mktnews/flash\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_51 = "/** HOT */\nimport { utils } from \"@findrss/util\";\nexport const version = \"1.0.0\";\nexport const category = \"动漫\";\nexport const order = 890;\n// Favicon: https://www.google.com/s2/favicons?domain=myanimelist.net&sz=32\nexport const platform = { name: \"MyAnimeList\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"myanimelist-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"myanimelist-favicon\\\"/></svg>\" };\nexport const tags = [\"动漫\", \"漫画\", \"小说\", \"英语\", \"日语\"];\n\nexport class MyanimelistHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const type = ctx.params.type || \"anime\";\n      if (![\"anime\", \"manga\", \"novels\"].includes(type)) return Result.Err(\"type 支持 anime（默认）、manga、novels\", \"INVALID_PARAMETER\");\n      const link = \"https://myanimelist.net/\" + (type === \"anime\" ? \"topanime.php\" : \"topmanga.php\" + (type === \"novels\" ? \"?type=novels\" : \"\"));\n      const fetched = await utils.request_text(ctx, link);\n      if (fetched.error) return fetched;\n      const parsed = utils.document_nodes(fetched.data);\n      if (parsed.error) return parsed;\n      const list = utils.rows(parsed.data, \"tr.ranking-list\");\n      if (list.error) return list;\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        const match = /^https:\\/\\/myanimelist\\.net\\/(anime|manga)\\/(\\d+)(?:\\/|$)/.exec(utils.attribute(row, \"h3 a\", \"href\"));\n        if (!match || match[1] !== (type === \"anime\" ? \"anime\" : \"manga\")) return Result.Err(\"MyAnimeList 作品链接无效\", \"UPSTREAM_INVALID_RESPONSE\");\n        const id = match[2];\n        if (seen.has(id)) continue;\n        seen.add(id);\n        const thumbnail = utils.absolute_url(utils.attribute(row, \".title img\", \"data-src\") || utils.attribute(row, \".title img\", \"src\"));\n        if (thumbnail.error) return thumbnail;\n        const rank = utils.field(row, \".rank span\"), text = utils.field(row, \"td.score .score-label\");\n        entries.push({ id: \"myanimelist:\" + match[1] + \":\" + id, title: utils.field(row, \"h3 a\"), link: \"https://myanimelist.net/\" + match[1] + \"/\" + id,\n          ...(thumbnail.data ? { thumbnail: thumbnail.data } : {}), rank: rank === \"\" ? null : Number(rank), pinned: false,\n          heat: { value: text === \"\" || text === \"N/A\" ? null : Number(text), unit: \"评分\", text } });\n      }\n      return Result.Ok({ category: type === \"novels\" ? \"小说\" : category, title: \"MyAnimeList · \" + ({ anime: \"动画\", manga: \"漫画\", novels: \"轻小说\" })[type] + \"评分榜\", link, entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\nconst script = new MyanimelistHotRank();\nexport const route = { name: \"MyAnimeList · 动漫/轻小说榜\", path: \"/myanimelist/top/:type?\", url: \"myanimelist.net\",\n  maintainers: [\"findrss\"], example: \"/myanimelist/top/anime\", parameters: { type: \"anime（默认）、manga、novels\" },\n  description: \"官网评分榜第一页，保留明确名次和评分，封面来自页面；支持动画、漫画及轻小说。\", handler: ctx => script.run(ctx) };\n";
const source_52 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"小说\";\nexport const order = 680;\n// Favicon: https://www.google.com/s2/favicons?domain=syosetu.com&sz=32\nexport const platform = { name: \"小説家になろう\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"narou-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"narou-favicon\\\"/></svg>\" };\nexport const tags = [\"小说\", \"排行榜\", \"日语\"];\n\n// Source: https://dev.syosetu.com/man/api/\nconst periods = {\n  daily: { order: \"dailypoint\", field: \"daily_point\", output: \"dp\", name: \"日间积分\" },\n  weekly: { order: \"weeklypoint\", field: \"weekly_point\", output: \"wp\", name: \"周间积分\" },\n  monthly: { order: \"monthlypoint\", field: \"monthly_point\", output: \"mp\", name: \"月间积分\" },\n  quarter: { order: \"quarterpoint\", field: \"quarter_point\", output: \"qp\", name: \"季度积分\" },\n  yearly: { order: \"yearlypoint\", field: \"yearly_point\", output: \"yp\", name: \"年度积分\" },\n  total: { order: \"hyoka\", field: \"global_point\", output: \"gp\", name: \"总积分\" },\n};\n\nexport class NarouHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const period = ctx.params.period || \"daily\";\n      if (!Object.hasOwn(periods, period)) return Result.Err(\"period 支持 daily（默认）、weekly、monthly、quarter、yearly、total\", \"INVALID_PARAMETER\");\n      const selected = periods[period];\n      const fetched = await utils.request_json(ctx, \"https://api.syosetu.com/novelapi/api/?out=json&lim=30&of=t-n-\" + selected.output + \"&order=\" + selected.order);\n      if (fetched.error) return fetched;\n      const list = utils.array_at(fetched.data);\n      if (list.error) return list;\n      if (!Number.isInteger(list.data[0]?.allcount) || list.data[0].allcount < 1 || list.data.length < 2) {\n        return Result.Err(\"なろう API 缺少作品列表或返回空榜单\", \"UPSTREAM_INVALID_RESPONSE\");\n      }\n      const entries = [], seen = new Set();\n      for (const row of list.data.slice(1)) {\n        const id = row?.ncode;\n        if (typeof id !== \"string\" || !/^N\\d{4,}[A-Z]+$/i.test(id)) return Result.Err(\"なろう作品 N 代码无效\", \"UPSTREAM_INVALID_RESPONSE\");\n        const ncode = id.toLowerCase();\n        if (seen.has(ncode)) continue;\n        seen.add(ncode);\n        const score = row[selected.field];\n        entries.push({ id: \"narou:novel:\" + ncode, title: utils.plain_text(row.title), link: \"https://ncode.syosetu.com/\" + ncode + \"/\",\n          rank: null, pinned: false, heat: { value: score ?? null, unit: selected.name, text: String(score ?? \"\") } });\n      }\n      return Result.Ok({ category, title: \"小説家になろう · \" + selected.name + \"榜\", link: \"https://yomou.syosetu.com/\", entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new NarouHotRank();\nexport const route = {\n  name: \"小説家になろう · 小说积分榜\", path: \"/narou/top/:period?\", url: \"syosetu.com\",\n  maintainers: [\"findrss\"], example: \"/narou/top/daily\", parameters: { period: \"daily（默认）、weekly、monthly、quarter、yearly、total\" },\n  description: \"官方小说 API 按对应周期积分降序返回前 30 部作品，非历史排名 API；保留积分与顺序，接口没有排名字段，rank 为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_53 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"新闻\";\nexport const order = 800;\n// Favicon: https://www.google.com/s2/favicons?domain=www.nhk.or.jp&sz=32\nexport const platform = { name: \"NHK\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"nhk-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"nhk-favicon\\\"/></svg>\" };\nexport const tags = [\"新闻\",\"日语\"];\n\nexport class NhkHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const fetched = await utils.request_text(ctx, \"https://www.nhk.or.jp/rss/news/cat0.xml\");\n      if (fetched.error) return fetched;\n      const list = utils.feed_items(fetched.data, \"https://news.web.nhk/newsweb/\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"NHK 未返回内容列表\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        if (seen.has(row.id)) continue;\n        seen.add(row.id);\n        entries.push({ id: \"nhk:\" + row.id, title: utils.plain_text(row.title), link: row.link,\n          rank: null, pinned: false, heat: { value: null, unit: \"热度\", text: \"\" } });\n      }\n      return Result.Ok({ category, title: \"NHK · 主要新闻\", link: \"https://news.web.nhk/newsweb/\", entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new NhkHotRank();\nexport const route = {\n  name: \"NHK · 主要新闻\", path: \"/nhk/headlines\", url: \"news.web.nhk\",\n  maintainers: [\"findrss\"], example: \"/nhk/headlines\", parameters: {},\n  description: \"官方 RSS/Atom 内容列表，保留上游选择和顺序。新闻及精选列表不冒充热度排名，未知排名与热度均为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_54 = "/** HOT */\nimport { utils } from \"@findrss/util\";\nexport const version = \"1.0.0\";\nexport const category = \"视频\";\nexport const order = 730;\n// Favicon: https://www.google.com/s2/favicons?domain=www.nicovideo.jp&sz=32\nexport const platform = { name: \"ニコニコ動画\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"niconico-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"niconico-favicon\\\"/></svg>\" };\nexport const tags = [\"视频\", \"排行榜\", \"日语\"];\n\nexport class NiconicoHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const link = \"https://www.nicovideo.jp/ranking\";\n      const fetched = await utils.request_text(ctx, link);\n      if (fetched.error) return fetched;\n      const parsed = utils.document_nodes(fetched.data);\n      if (parsed.error) return parsed;\n      const data = parseJSON(utils.attribute(parsed.data, 'meta[name=\"server-response\"]', \"content\"));\n      if (data.error) return data;\n      if (data.data?.meta?.status !== 200) return Result.Err(\"Niconico 榜单请求未成功\", \"UPSTREAM_INVALID_RESPONSE\");\n      const list = utils.array_at(data.data, \"data.response.$getTeibanRanking.data.items\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"Niconico 综合榜为空\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        const id = row?.id;\n        if (typeof id !== \"string\" || !/^(?:(?:sm|so|nm)\\d+|\\d+)$/.test(id)) return Result.Err(\"Niconico 视频 ID 无效\", \"UPSTREAM_INVALID_RESPONSE\");\n        if (seen.has(id)) continue;\n        seen.add(id);\n        const thumbnail = utils.absolute_url(row.thumbnail?.middleUrl || row.thumbnail?.url);\n        if (thumbnail.error) return thumbnail;\n        entries.push({ id: \"niconico:\" + id, title: utils.plain_text(row.title), link: \"https://www.nicovideo.jp/watch/\" + id,\n          ...(thumbnail.data ? { thumbnail: thumbnail.data } : {}), rank: null, pinned: false,\n          heat: { value: row.count?.view ?? null, unit: \"播放\", text: String(row.count?.view ?? \"\") } });\n      }\n      return Result.Ok({ category, title: \"ニコニコ動画 · 综合排行榜\", link, entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\nconst script = new NiconicoHotRank();\nexport const route = { name: \"ニコニコ動画 · 综合排行榜\", path: \"/niconico/rank\", url: \"www.nicovideo.jp\",\n  maintainers: [\"findrss\"], example: \"/niconico/rank\", parameters: {},\n  description: \"读取官网 server-response 中的综合 Teiban 榜，保留上游顺序和播放数；数据无显式数字排名字段，rank 为 null。\", handler: ctx => script.run(ctx) };\n";
const source_55 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"社区\";\nexport const order = 340;\n// Favicon: https://static.nowcoder.com/fe/file/images/nowpick/web/www-favicon.ico\nexport const platform = {\n  name: \"牛客\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"nowcoder-hot-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"nowcoder-hot-favicon\\\"/></svg>\",\n};\nimport { utils } from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"nowcoder\",\n  \"name\": \"牛客\",\n  \"home\": \"https://www.nowcoder.com\"\n};\nexport class NowcoderHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const request_options = {};\n      request_options.headers = {\n        Referer: source.home,\n        ...request_options.headers\n      };\n      const fetched = await utils.request_json(ctx, \"https://gw-c.nowcoder.com/api/sparta/hot-search/top-hot-pc?size=20&_=\" + Date.now() + \"&t=\", request_options);\n      if (fetched.error) return fetched;\n      const data = fetched.data;\n      if (!data || typeof data !== 'object') return Result.Err('上游未返回数据对象', 'UPSTREAM_INVALID_RESPONSE');\n      if (data.need_force_login) return Result.Err('上游要求登录，请更新并授权 Cookie', 'UPSTREAM_AUTH_REQUIRED');\n      if (data.error || data.errors?.length || (typeof data.code === 'number' && data.code < 0) || (data.error_code !== undefined && data.error_code !== 0)) return Result.Err('上游拒绝请求，请检查账户权限或验证页面', 'UPSTREAM_INVALID_RESPONSE');\n      const list = utils.array_at(data, \"data.result\");\n      if (list.error) return list;\n      const rows = list.data;\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        if (row.type !== 74 && row.type !== 0) continue;\n        const id = utils.identity(row.type === 74 ? row.uuid : row.id);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url('https://www.nowcoder.com/' + (row.type === 74 ? 'feed/main/detail/' : 'discuss/') + encodeURIComponent(id.data), source.home);\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = row.rank;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String('' ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.title),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n}\nconst script = new NowcoderHotRank();\nexport const route = {\n  \"name\": \"牛客\",\n  \"path\": \"/nowcoder/hot\",\n  \"url\": \"www.nowcoder.com\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/nowcoder/hot\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_56 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"新闻\";\nexport const order = 790;\n// Favicon: https://www.google.com/s2/favicons?domain=www.npr.org&sz=32\nexport const platform = { name: \"NPR\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"npr-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"npr-favicon\\\"/></svg>\" };\nexport const tags = [\"新闻\",\"英语\"];\n\nexport class NprHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const fetched = await utils.request_text(ctx, \"https://feeds.npr.org/1001/rss.xml\");\n      if (fetched.error) return fetched;\n      const list = utils.feed_items(fetched.data, \"https://www.npr.org/\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"NPR 未返回内容列表\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        if (seen.has(row.id)) continue;\n        seen.add(row.id);\n        entries.push({ id: \"npr:\" + row.id, title: utils.plain_text(row.title), link: row.link,\n          rank: null, pinned: false, heat: { value: null, unit: \"热度\", text: \"\" } });\n      }\n      return Result.Ok({ category, title: \"NPR · Top Stories\", link: \"https://www.npr.org/\", entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new NprHotRank();\nexport const route = {\n  name: \"NPR · Top Stories\", path: \"/npr/headlines\", url: \"www.npr.org\",\n  maintainers: [\"findrss\"], example: \"/npr/headlines\", parameters: {},\n  description: \"官方 RSS/Atom 内容列表，保留上游选择和顺序。新闻及精选列表不冒充热度排名，未知排名与热度均为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_57 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"科技\";\nexport const order = 350;\n// Favicon: https://raw.githubusercontent.com/newsnext/newsnow/main/public/icons/pcbeta.png\nexport const platform = {\n  name: \"远景论坛\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"pcbeta-windows11-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"pcbeta-windows11-favicon\\\"/></svg>\",\n};\nimport { utils } from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"pcbeta-windows11\",\n  \"name\": \"远景论坛 · Win11\",\n  \"home\": \"https://bbs.pcbeta.com\"\n};\nexport class PcbetaWindows11HotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const request_options = {};\n      request_options.headers = {\n        Referer: source.home,\n        ...request_options.headers\n      };\n      const fetched = await utils.request_text(ctx, \"https://bbs.pcbeta.com/forum.php?mod=rss&fid=563&auth=0\", request_options);\n      if (fetched.error) return fetched;\n      const list = utils.feed_items(fetched.data, \"https://bbs.pcbeta.com/forum.php?mod=rss&fid=563&auth=0\");\n      if (list.error) return list;\n      const rows = list.data;\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        const id = utils.identity(row.id);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url(row.link, source.home);\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = null;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String('' ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.title),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n}\nconst script = new PcbetaWindows11HotRank();\nexport const route = {\n  \"name\": \"远景论坛 · Win11\",\n  \"path\": \"/pcbeta/windows11\",\n  \"url\": \"bbs.pcbeta.com\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/pcbeta/windows11\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_58 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"科技\";\nexport const order = 360;\n// Favicon: https://ph-static.imgix.net/ph-favicon-brand-500.ico\nexport const platform = {\n  name: \"Product Hunt\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"producthunt-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"producthunt-favicon\\\"/></svg>\",\n};\nimport { utils } from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"producthunt\",\n  \"name\": \"Product Hunt\",\n  \"home\": \"https://www.producthunt.com/\"\n};\nexport class ProducthuntHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const request_options = {};\n      request_options.headers = {\n        Referer: source.home,\n        ...request_options.headers\n      };\n      const fetched = await utils.request_text(ctx, \"https://www.producthunt.com/feed\", request_options);\n      if (fetched.error) return fetched;\n      const list = utils.feed_items(fetched.data, \"https://www.producthunt.com/feed\");\n      if (list.error) return list;\n      const rows = list.data;\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        const id = utils.identity(row.id);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url(row.link, source.home);\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = null;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String('' ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.title),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n}\nconst script = new ProducthuntHotRank();\nexport const route = {\n  \"name\": \"Product Hunt\",\n  \"path\": \"/producthunt\",\n  \"url\": \"www.producthunt.com\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/producthunt\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_59 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.1.1\";\nexport const category = \"小说\";\nexport const order = 370;\nexport const platform = {\n  name: \"起点\",\n  icon: '<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 32 32\" role=\"img\" aria-labelledby=\"qidian-title\" data-n=\"qidian-platform-icon\">\\n  <title id=\"qidian-title\" data-n=\"qidian-title\">起点中文网</title>\\n  <defs data-n=\"qidian-palette\">\\n    <linearGradient id=\"qidian-red\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\" data-n=\"qidian-red-gradient\">\\n      <stop stop-color=\"#f32236\" data-n=\"qidian-red-top\"/>\\n      <stop offset=\"1\" stop-color=\"#e60012\" data-n=\"qidian-red-bottom\"/>\\n    </linearGradient>\\n  </defs>\\n  <rect width=\"32\" height=\"32\" rx=\"4.8\" fill=\"url(#qidian-red)\" data-n=\"qidian-background\"/>\\n  <path fill=\"#fff\" d=\"M6 9.2h1.2v2H9v1.1H7.2v2.1h2v1.1h-2v2.1h2v1.1h-2v2.4H6v-5.6H3.5v-1.1H6v-2.1H3.8v-1.1H6Zm-2.5 8.1h1.2v2.4c1.1 1.1 2.2 1.5 4.1 1.5h6.1v1.1H8.8c-2.1 0-3.4-.4-4.6-1.5l-.5 1.4H2.5c.7-1.4 1-3 1-4.9Zm6.6-7.2h4.6v5h-3.4v4.2h2.3v-2.9h1.1v3.3c0 .5-.3.7-.8.7h-2.9c-.6 0-.9-.3-.9-.9v-5.5h3.4v-2.8h-3.4Z\" data-n=\"qidian-character-qi\"/>\\n  <path fill=\"#fff\" fill-rule=\"evenodd\" d=\"M21.2 9.2h1.2v1.4h5.3v1.2h-5.3v1.5h6.1v5.3H18v-5.3h3.2Zm-2 5.3v2.9h8.1v-2.9Z\" data-n=\"qidian-character-dian-body\"/>\\n  <path fill=\"#fff\" d=\"m18.1 19.8 1.1.3-.8 2.1-1.1-.3Zm3.1.2h1.1v2h-1.1Zm3 0h1.1l.2 2h-1.1Zm3.1-.1 1.1-.2.6 2.1-1.1.2Z\" data-n=\"qidian-character-dian-dots\"/>\\n</svg>',\n};\nexport const tags = [\"小说\", \"排行榜\"];\n\nconst rank_names = {\n  yuepiao: \"月票榜\",\n  hotsales: \"畅销榜\",\n  readindex: \"阅读榜\",\n  newfans: \"书友榜\",\n  rec: \"推荐榜\",\n  update: \"更新榜\",\n  sign: \"签约榜\",\n  newbook: \"新书榜\",\n  newauthor: \"新人榜\",\n  collect: \"收藏榜\",\n  free: \"免费榜\",\n};\nconst gender_types = {\n  male: [\n    \"yuepiao\",\n    \"hotsales\",\n    \"readindex\",\n    \"newfans\",\n    \"rec\",\n    \"update\",\n    \"sign\",\n    \"newbook\",\n    \"newauthor\",\n  ],\n  female: [\n    \"yuepiao\",\n    \"hotsales\",\n    \"readindex\",\n    \"newfans\",\n    \"rec\",\n    \"update\",\n    \"collect\",\n    \"free\",\n  ],\n};\n\nexport class QidianHotRank extends HotRankScript {\n  constructor(type, gender) {\n    super();\n    this.type = type;\n    this.gender = gender;\n  }\n\n  async fetch(ctx) {\n    try {\n      const { type, gender } = this;\n      if (\n        ![\"male\", \"female\"].includes(gender) ||\n        !gender_types[gender].includes(type)\n      ) {\n        return Result.Err(\n          \"gender 仅支持 male、female；type 必须为对应频道的官网榜单类型\",\n          \"INVALID_PARAMETER\",\n        );\n      }\n      const category_id = String(ctx.query.category || \"-1\");\n      const period = String(ctx.query.period || \"\");\n      const periods =\n        type === \"rec\"\n          ? { week: \"3\", month: \"2\", all: \"1\" }\n          : type === \"newfans\"\n            ? { week: \"3\", month: \"2\" }\n            : {};\n      if (\n        !/^(?:-1|[1-9]\\d{0,5})$/.test(category_id) ||\n        (period &&\n          !(type === \"yuepiao\"\n            ? /^20\\d{2}(?:0[1-9]|1[0-2])$/.test(period)\n            : Object.keys(periods).includes(period)))\n      ) {\n        return Result.Err(\n          \"category 必须为官网分类数字 ID；period：月票榜用 YYYYMM，推荐榜用 week/month/all，书友榜用 week/month\",\n          \"INVALID_PARAMETER\",\n        );\n      }\n      const home =\n        gender === \"female\" ? \"https://m.qdmm.com\" : \"https://m.qidian.com\";\n      const link =\n        home +\n        \"/rank/\" +\n        type +\n        \"/\" +\n        (category_id !== \"-1\" || period ? \"catid\" + category_id + \"/\" : \"\") +\n        (period ? (type === \"yuepiao\" ? period : periods[period]) + \"/\" : \"\");\n      const fetched = await utils.request_text(ctx, link, {\n        headers: {\n          Referer: home + \"/\",\n          Accept: \"text/html,application/xhtml+xml\",\n          \"User-Agent\":\n            \"Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1\",\n        },\n      });\n      if (fetched.error) return fetched;\n      const context = utils.embedded_json(\n        fetched.data,\n        /<script\\b[^>]*\\bid=[\"']vite-plugin-ssr_pageContext[\"'][^>]*>/i,\n      );\n      if (context.error) return context;\n      const page = context.data.pageContext?.pageProps?.pageData;\n      if (page?.gender && page.gender !== gender)\n        return Result.Err(\n          \"起点返回了其他频道榜单\",\n          \"UPSTREAM_INVALID_RESPONSE\",\n        );\n      const list = utils.array_at(\n        context.data,\n        \"pageContext.pageProps.pageData.records\",\n      );\n      if (list.error) return list;\n      if (!list.data.length)\n        return Result.Err(\n          \"起点榜单为空，可能为验证页面\",\n          \"UPSTREAM_INVALID_RESPONSE\",\n        );\n      const entries = [],\n        seen = new Set();\n      for (const row of list.data) {\n        const id = utils.identity(row.bid);\n        if (id.error) return id;\n        if (!/^\\d{1,24}$/.test(id.data))\n          return Result.Err(\"起点书籍 ID 无效\", \"UPSTREAM_INVALID_RESPONSE\");\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const text = String(row.rankCnt ?? \"\").trim();\n        const heat = /^([\\d,]+(?:\\.\\d+)?)(万|亿)?/.exec(text);\n        entries.push({\n          id: \"qidian:book:\" + id.data,\n          title: utils.plain_text(row.bName),\n          link: home + \"/book/\" + id.data + \"/\",\n          thumbnail:\n            \"https://bookcover.yuewen.com/qdbimg/349573/\" + id.data + \"/180\",\n          rank:\n            row.rankNum == null || row.rankNum === \"\"\n              ? null\n              : Number(row.rankNum),\n          pinned: false,\n          heat: {\n            value: heat\n              ? Number(heat[1].replace(/,/g, \"\")) *\n                (heat[2] === \"亿\" ? 1e8 : heat[2] === \"万\" ? 1e4 : 1)\n              : null,\n            unit:\n              {\n                yuepiao: \"月票\",\n                newfans: \"书友\",\n                rec: \"推荐\",\n                update: \"更新字数\",\n                collect: \"收藏\",\n              }[type] || \"热度\",\n            text,\n          },\n        });\n      }\n      ctx.log(\"起点榜单解析完成\", {\n        type,\n        gender,\n        category: category_id,\n        period,\n        count: entries.length,\n      });\n      return Result.Ok({\n        category,\n        title:\n          \"起点 · \" +\n          (gender === \"female\" ? \"女频\" : \"\") +\n          rank_names[type] +\n          (category_id !== \"-1\"\n            ? \" · \" +\n              (page?.filters\n                ?.find((filter) => filter.key === \"catId\")\n                ?.items?.find((item) => String(item.value) === category_id)\n                ?.text || category_id)\n            : \"\") +\n          (period\n            ? \" · \" +\n              ({ week: \"周榜\", month: \"月榜\", all: \"总榜\" }[period] || period)\n            : \"\"),\n        link,\n        entries,\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\");\n    }\n  }\n}\n\nconst rank_metadata = {\n  url: \"m.qidian.com\",\n  maintainers: [\"findrss\"],\n  description:\n    \"读取官网移动端榜单第一页并返回封面。?category=21 按分类；?period=YYYYMM（月票）或 week/month/all（推荐）、week/month（书友）；未知排名和热度为 null。\",\n};\n\nexport const routes = [\n  {\n    ...rank_metadata,\n    name: \"起点 · 月票榜\",\n    path: \"/qidian/rank/yuepiao\",\n    handler: (ctx) => new QidianHotRank(\"yuepiao\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 畅销榜\",\n    path: \"/qidian/rank/hotsales\",\n    handler: (ctx) => new QidianHotRank(\"hotsales\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 阅读榜\",\n    path: \"/qidian/rank/readindex\",\n    handler: (ctx) => new QidianHotRank(\"readindex\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 书友榜\",\n    path: \"/qidian/rank/newfans\",\n    handler: (ctx) => new QidianHotRank(\"newfans\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 推荐榜\",\n    path: \"/qidian/rank/rec\",\n    handler: (ctx) => new QidianHotRank(\"rec\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 更新榜\",\n    path: \"/qidian/rank/update\",\n    handler: (ctx) => new QidianHotRank(\"update\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 签约榜\",\n    path: \"/qidian/rank/sign\",\n    handler: (ctx) => new QidianHotRank(\"sign\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 新书榜\",\n    path: \"/qidian/rank/newbook\",\n    handler: (ctx) => new QidianHotRank(\"newbook\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 新人榜\",\n    path: \"/qidian/rank/newauthor\",\n    handler: (ctx) => new QidianHotRank(\"newauthor\", \"male\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频月票榜\",\n    path: \"/qidian/rank/yuepiao/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"yuepiao\", \"female\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频畅销榜\",\n    path: \"/qidian/rank/hotsales/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"hotsales\", \"female\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频阅读榜\",\n    path: \"/qidian/rank/readindex/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"readindex\", \"female\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频书友榜\",\n    path: \"/qidian/rank/newfans/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"newfans\", \"female\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频推荐榜\",\n    path: \"/qidian/rank/rec/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"rec\", \"female\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频更新榜\",\n    path: \"/qidian/rank/update/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"update\", \"female\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频收藏榜\",\n    path: \"/qidian/rank/collect/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"collect\", \"female\").run(ctx),\n  },\n  {\n    ...rank_metadata,\n    name: \"起点 · 女频免费榜\",\n    path: \"/qidian/rank/free/female\",\n    url: \"m.qdmm.com\",\n    handler: (ctx) => new QidianHotRank(\"free\", \"female\").run(ctx),\n  },\n];\n";
const source_60 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"科技\";\nexport const order = 750;\n// Favicon: https://www.google.com/s2/favicons?domain=qiita.com&sz=32\nexport const platform = { name: \"Qiita\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"qiita-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"qiita-favicon\\\"/></svg>\" };\nexport const tags = [\"社区\",\"日语\"];\n\nexport class QiitaHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const fetched = await utils.request_text(ctx, \"https://qiita.com/popular-items/feed\");\n      if (fetched.error) return fetched;\n      const list = utils.feed_items(fetched.data, \"https://qiita.com/\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"Qiita 未返回内容列表\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        if (seen.has(row.id)) continue;\n        seen.add(row.id);\n        entries.push({ id: \"qiita:\" + row.id, title: utils.plain_text(row.title), link: row.link,\n          rank: null, pinned: false, heat: { value: null, unit: \"热度\", text: \"\" } });\n      }\n      return Result.Ok({ category, title: \"Qiita · 热门文章\", link: \"https://qiita.com/\", entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new QiitaHotRank();\nexport const route = {\n  name: \"Qiita · 热门文章\", path: \"/qiita/hot\", url: \"qiita.com\",\n  maintainers: [\"findrss\"], example: \"/qiita/hot\", parameters: {},\n  description: \"官方 RSS/Atom 内容列表，保留上游选择和顺序。新闻及精选列表不冒充热度排名，未知排名与热度均为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_61 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.2\";\nexport const category = \"小说\";\nexport const order = 380;\n// Favicon: https://www.google.com/s2/favicons?domain=www.qimao.com&sz=64\nexport const platform = {\n  name: \"七猫小说\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"qimao-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"qimao-favicon\\\"/></svg>\",\n};\nexport const tags = [\"小说\", \"排行榜\"];\nexport const permissions = {\n  cookies: [{\n    id: \"qimao\",\n    origin: \"https://www.qimao.com\",\n    path_prefix: \"/paihang/\",\n    names: [\"acw_tc\", \"acw_sc__v2\", \"acw_sc__v3\"],\n    purpose: \"携带七猫访问验证 Cookie 读取小说排行榜\",\n  }],\n};\n\nexport class QimaoHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const gender = ctx.params.gender || \"boy\";\n      const type = ctx.params.type || \"hot\";\n      const period = ctx.params.period || \"date\";\n      if (![\"boy\", \"girl\"].includes(gender) || ![\"hot\", \"new\", \"over\", \"collect\", \"update\"].includes(type)\n        || ![\"date\", \"month\"].includes(period) || [\"collect\", \"update\"].includes(type) && period !== \"date\") {\n        return Result.Err(\"gender 仅支持 boy、girl；type 支持 hot、new、over、collect、update；前三类支持 date/month，收藏和更新榜使用 date\", \"INVALID_PARAMETER\");\n      }\n      const link = \"https://www.qimao.com/paihang/\" + gender + \"/\" + type + \"/\" + period + \"/\";\n      const acquired = await ctx.cookies.get(\"qimao\");\n      if (acquired.error) return acquired;\n      const fetched = await utils.request_text(ctx, link, {\n        cookies: acquired.data,\n        headers: { Referer: \"https://www.qimao.com/\" },\n      });\n      if (fetched.error) return fetched;\n      if (/aliyun_waf_|AliyunCaptcha|<title>\\s*(?:滑动验证页面|访问验证|Verification)\\s*<\\/title>/i.test(fetched.data)) {\n        return Result.Err(\"七猫返回访问验证页，请手动完成官网验证，在后台同步有效的 qimao.com 验证 Cookie 并确认脚本 Cookie 授权；若仍失败，可能是上游限制了服务端 IP\", \"UPSTREAM_INVALID_RESPONSE\");\n      }\n      const parsed = utils.document_nodes(fetched.data);\n      if (parsed.error) return parsed;\n      const list = utils.rows(parsed.data, \".rank-list .rank-list-item\");\n      if (list.error) return list;\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        const book = utils.absolute_url(utils.attribute(row, \"a.s-book-title\", \"href\"), link);\n        if (book.error) return book;\n        const id = /^https:\\/\\/www\\.qimao\\.com\\/shuku\\/(\\d+)\\/?$/.exec(book.data)?.[1];\n        if (!id) return Result.Err(\"七猫书籍链接无效\", \"UPSTREAM_INVALID_RESPONSE\");\n        if (seen.has(id)) continue;\n        seen.add(id);\n        const thumbnail = utils.absolute_url(utils.attribute(row, \".pic img\", \"data-src\") || utils.attribute(row, \".pic img\", \"src\"), link);\n        if (thumbnail.error) return thumbnail;\n        const rank = utils.field(row, \".rank-number\");\n        const text = utils.field(row, \".rank-num\") + utils.field(row, \".rank-unit\");\n        const heat = /^([\\d,]+(?:\\.\\d+)?)(万|亿)?$/.exec(text);\n        entries.push({\n          id: \"qimao:book:\" + id,\n          title: utils.field(row, \"a.s-book-title\"),\n          link: book.data,\n          ...(thumbnail.data ? { thumbnail: thumbnail.data } : {}),\n          rank: rank === \"\" ? null : Number(rank),\n          pinned: false,\n          heat: {\n            value: heat ? Number(heat[1].replace(/,/g, \"\")) * (heat[2] === \"亿\" ? 1e8 : heat[2] === \"万\" ? 1e4 : 1) : null,\n            unit: type === \"collect\" ? \"收藏\" : type === \"update\" ? \"更新字数\" : \"热度\",\n            text,\n          },\n        });\n      }\n      const title = \"七猫小说 · \" + (gender === \"boy\" ? \"男频\" : \"女频\") + ({ hot: \"大热榜\", new: \"新书榜\", over: \"完结榜\", collect: \"收藏榜\", update: \"更新榜\" })[type] + (period === \"month\" ? \" · 月榜\" : \"\");\n      ctx.log(\"七猫榜单解析完成\", { gender, type, period, count: entries.length });\n      return Result.Ok({ category, title, link, entries });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\");\n    }\n  }\n}\n\nconst script = new QimaoHotRank();\nexport const route = {\n  name: \"七猫小说排行榜\",\n  path: \"/qimao/rank/:gender?/:type?/:period?\",\n  url: \"www.qimao.com\",\n  maintainers: [\"findrss\"],\n  example: \"/qimao/rank/boy/hot\",\n  parameters: { gender: \"boy（男频，默认）、girl（女频）\", type: \"hot 大热榜（默认）、new 新书榜、over 完结榜、collect 收藏榜、update 更新榜\", period: \"date（默认）、month；大热/新书/完结支持日榜和月榜，收藏按总收藏数、更新按近 30 天更新字数排行，仅支持 date\" },\n  description: \"覆盖官网男女频全部 5 类榜单及可用周期，读取第一页并返回封面；保留上游排名与热度，未提供的数据为 null。需授权七猫访问验证 Cookie；遇到验证页请手动完成官网验证后同步 Cookie。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_62 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"娱乐\";\nexport const order = 390;\n// Favicon: https://vfiles.gtimg.cn/wuji_dashboard/xy/starter/4ea79867.png\nexport const platform = {\n  name: \"腾讯视频\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"qqvideo-hot-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"qqvideo-hot-favicon\\\"/></svg>\",\n};\nimport { utils } from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"qqvideo-tv-hotsearch\",\n  \"name\": \"腾讯视频 · 热搜榜\",\n  \"home\": \"https://v.qq.com/channel/tv\"\n};\nexport class QqvideoHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const request_options = {\n        method: \"POST\",\n        headers: {\n          Referer: \"https://v.qq.com/\",\n          \"Content-Type\": \"application/json\"\n        },\n        body: JSON.stringify({\n          page_params: {\n            rank_channel_id: \"100113\",\n            rank_name: \"HotSearch\",\n            rank_page_size: \"30\",\n            tab_mvl_sub_mod_id: \"792ac_19e77Sub_1b2\",\n            tab_name: \"热搜榜\",\n            tab_type: \"hot_rank\",\n            tab_vl_data_src: \"f5200deb4596bbf3\",\n            page_id: \"scms_shake\",\n            page_type: \"scms_shake\",\n            source_key: \"\",\n            tag_id: \"\",\n            tag_type: \"\",\n            new_mark_label_enabled: \"1\",\n          },\n          page_context: {\n            page_index: \"1\",\n          },\n          flip_info: {\n            page_strategy_id: \"\",\n            page_module_id: \"792ac_19e77\",\n            module_strategy_id: {},\n            sub_module_id: \"20251106065177\",\n            flip_params: {\n              folding_screen_show_num: \"\",\n              is_mvl: \"1\",\n              mvl_strategy_info: \"{\\\"default_strategy_id\\\":\\\"06755800b45b49238582a6fa1ad0f5c5\\\",\\\"default_version\\\":\\\"3836\\\",\\\"hit_page_uuid\\\":\\\"b5080d97dc694a5fb50eb9e7c99326ac\\\",\\\"hit_tab_info\\\":null,\\\"gray_status_info\\\":null,\\\"bypass_to_un_exp_id\\\":\\\"\\\"}\",\n              mvl_sub_mod_id: \"20251106065177\",\n              pad_post_show_num: \"\",\n              pad_pro_post_show_num: \"\",\n              pad_pro_small_hor_pic_display_num: \"\",\n              pad_small_hor_pic_display_num: \"\",\n              page_id: \"scms_shake\",\n              page_num: \"0\",\n              page_type: \"scms_shake\",\n              post_show_num: \"\",\n              shake_size: \"\",\n              small_hor_pic_display_num: \"\",\n              source_key: \"100113\",\n              un_policy_id: \"06755800b45b49238582a6fa1ad0f5c5\",\n              un_strategy_id: \"06755800b45b49238582a6fa1ad0f5c5\",\n            },\n            relace_children_key: [],\n          },\n        }),\n      };\n      request_options.headers = {\n        Referer: source.home,\n        ...request_options.headers\n      };\n      const fetched = await utils.request_json(ctx, \"https://pbaccess.video.qq.com/trpc.vector_layout.page_view.PageService/getCard?video_appid=3000010&vversion_platform=2\", request_options);\n      if (fetched.error) return fetched;\n      const data = fetched.data;\n      if (!data || typeof data !== 'object') return Result.Err('上游未返回数据对象', 'UPSTREAM_INVALID_RESPONSE');\n      if (data.need_force_login) return Result.Err('上游要求登录，请更新并授权 Cookie', 'UPSTREAM_AUTH_REQUIRED');\n      if (data.error || data.errors?.length || (typeof data.code === 'number' && data.code < 0) || (data.error_code !== undefined && data.error_code !== 0) || (data.ret !== undefined && data.ret !== 0)) return Result.Err('上游拒绝请求，请检查账户权限或验证页面', 'UPSTREAM_INVALID_RESPONSE');\n      const list = utils.array_at(data, \"data.card.children_list.list.cards\");\n      if (list.error) return list;\n      const rows = list.data;\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        const id = utils.identity(row.id);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url('https://v.qq.com/x/cover/' + encodeURIComponent(id.data) + '.html', source.home);\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = row.params?.rank;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String(row.params?.hot_value ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.params?.title),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n}\nconst script = new QqvideoHotRank();\nexport const route = {\n  \"name\": \"腾讯视频 · 热搜榜\",\n  \"path\": \"/qqvideo/hot\",\n  \"url\": \"v.qq.com\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/qqvideo/hot\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_63 = "/** HOT */\nimport { utils } from \"@findrss/util\";\nexport const version = \"1.0.0\";\nexport const category = \"社交\";\nexport const order = 840;\n// Favicon: https://www.google.com/s2/favicons?domain=www.reddit.com&sz=32\nexport const platform = { name: \"Reddit\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"reddit-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"reddit-favicon\\\"/></svg>\" };\nexport const tags = [\"社媒\", \"社区\", \"英语\"];\n\nexport class RedditHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const subreddit = ctx.params.subreddit || \"popular\", sort = ctx.params.sort || \"hot\", period = ctx.query.period || \"day\";\n      if (!/^[a-zA-Z0-9_]{2,32}$/.test(subreddit) || ![\"hot\", \"top\", \"rising\"].includes(sort) || ![\"day\", \"week\", \"month\", \"year\", \"all\"].includes(period)\n        || sort !== \"top\" && ctx.query.period) return Result.Err(\"subreddit 使用版块名称；sort 支持 hot、top、rising；period 仅 top 支持 day/week/month/year/all\", \"INVALID_PARAMETER\");\n      const link = \"https://www.reddit.com/r/\" + subreddit + \"/\" + sort + \"/\";\n      const fetched = await utils.request_json(ctx, link.slice(0, -1) + \".json?limit=30&raw_json=1\" + (sort === \"top\" ? \"&t=\" + period : \"\"),\n        { headers: { \"User-Agent\": \"findrss-worker/1.0 (HotRankScript)\" } });\n      if (fetched.error) return fetched;\n      const list = utils.array_at(fetched.data, \"data.children\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"Reddit 榜单为空或未开放访问\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const item of list.data) {\n        const row = item?.data;\n        if (item?.kind !== \"t3\" || typeof row?.id !== \"string\" || !/^[a-z0-9]+$/.test(row.id)) return Result.Err(\"Reddit 帖子数据无效\", \"UPSTREAM_INVALID_RESPONSE\");\n        if (seen.has(row.id)) continue;\n        seen.add(row.id);\n        const score = row.score;\n        const thumbnail = /^https?:\\/\\//i.test(row.thumbnail || \"\") ? utils.absolute_url(row.thumbnail) : Result.Ok(\"\");\n        if (thumbnail.error) return thumbnail;\n        entries.push({ id: \"reddit:post:\" + row.id, title: utils.plain_text(row.title), link: \"https://www.reddit.com/comments/\" + row.id + \"/\",\n          ...(thumbnail.data ? { thumbnail: thumbnail.data } : {}), rank: null, pinned: row.stickied === true,\n          heat: { value: typeof score === \"number\" && score >= 0 ? score : null, unit: \"得分\", text: String(score ?? \"\") } });\n      }\n      return Result.Ok({ category, title: \"Reddit · r/\" + subreddit + \" · \" + sort, link, entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\nconst script = new RedditHotRank();\nexport const route = { name: \"Reddit · 社区热门\", path: \"/reddit/:subreddit?/:sort?\", url: \"www.reddit.com\",\n  maintainers: [\"findrss\"], example: \"/reddit/popular/hot\", parameters: { subreddit: \"popular（默认）、news、worldnews 等版块\", sort: \"hot（默认）、top、rising\", period: \"查询参数，仅 top 使用：day（默认）、week、month、year、all\" },\n  description: \"公开 Listing JSON，服务端 IP 可能被 Reddit 拒绝，未提供 OAuth 流程；只在允许访问的环境使用，403 会报错而不输出空榜单。\", handler: ctx => script.run(ctx) };\n";
const source_64 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"科技\";\nexport const order = 760;\n// Favicon: https://www.google.com/s2/favicons?domain=slashdot.org&sz=32\nexport const platform = { name: \"Slashdot\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"slashdot-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"slashdot-favicon\\\"/></svg>\" };\nexport const tags = [\"社区\",\"英语\"];\n\nexport class SlashdotHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const fetched = await utils.request_text(ctx, \"https://rss.slashdot.org/Slashdot/slashdotMain\");\n      if (fetched.error) return fetched;\n      const list = utils.feed_items(fetched.data, \"https://slashdot.org/\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"Slashdot 未返回内容列表\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        if (seen.has(row.id)) continue;\n        seen.add(row.id);\n        entries.push({ id: \"slashdot:\" + row.id, title: utils.plain_text(row.title), link: row.link,\n          rank: null, pinned: false, heat: { value: null, unit: \"热度\", text: \"\" } });\n      }\n      return Result.Ok({ category, title: \"Slashdot · 科技资讯\", link: \"https://slashdot.org/\", entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new SlashdotHotRank();\nexport const route = {\n  name: \"Slashdot · 科技资讯\", path: \"/slashdot/headlines\", url: \"slashdot.org\",\n  maintainers: [\"findrss\"], example: \"/slashdot/headlines\", parameters: {},\n  description: \"官方 RSS/Atom 内容列表，保留上游选择和顺序。新闻及精选列表不冒充热度排名，未知排名与热度均为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
