const source_74 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"社交\";\nexport const order = 710;\n// Favicon: https://www.google.com/s2/favicons?domain=www.tiktok.com&sz=32\nexport const platform = { name: \"TikTok\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"tiktok-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"tiktok-favicon\\\"/></svg>\" };\nexport const tags = [\"短视频\", \"话题\", \"英语\", \"日语\"];\nexport const config_schema = { type: \"object\", additionalProperties: false, properties: {\n  advertiser_id: { type: \"string\", title: \"TikTok Advertiser ID\", default: \"\", pattern: \"^\\\\d*$\", maxLength: 32 },\n  access_token: { type: \"string\", title: \"TikTok Business Access Token\", description: \"需获得 Discovery API 权限。配置按脚本元数据保存，请仅向受信管理员开放后台。\", writeOnly: true, default: \"\", maxLength: 4096 },\n} };\n\n// Source: https://business-api.tiktok.com/portal/docs?id=1825119032526849\nexport class TiktokHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const country = String(ctx.params.country || \"US\").toUpperCase(), days = ctx.params.days || \"7\";\n      if (!/^[A-Z]{2}$/.test(country) || ![\"1\", \"7\", \"30\", \"120\"].includes(days)) return Result.Err(\"country 使用 US、JP 等地区代码；days 支持 1、7（默认）、30、120\", \"INVALID_PARAMETER\");\n      const { advertiser_id, access_token } = ctx.config;\n      if (!advertiser_id || !access_token.trim()) return Result.Err(\"请在脚本配置中填写 advertiser_id 和具有 Discovery API 权限的 access_token\", \"INVALID_PARAMETER\");\n      const fetched = await utils.request_json(ctx, \"https://business-api.tiktok.com/open_api/v1.3/discovery/trending_list/?discovery_type=HASHTAG&advertiser_id=\" + advertiser_id + \"&country_code=\" + country + \"&category_name=ALL&date_range=\" + days + \"DAY\",\n        { headers: { \"Access-Token\": access_token.trim() } });\n      if (fetched.error) return fetched;\n      if (fetched.data?.code !== 0) return Result.Err(\"TikTok Discovery API 拒绝请求，请检查令牌、广告账户及接口权限\", \"UPSTREAM_INVALID_RESPONSE\");\n      const list = utils.array_at(fetched.data, \"data.list\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"TikTok 未返回热门话题\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        const id = utils.identity(row?.hashtag_id);\n        if (id.error) return id;\n        if (!/^\\d+$/.test(id.data) || typeof row.hashtag_name !== \"string\" || !row.hashtag_name.trim()) return Result.Err(\"TikTok 话题 ID 或名称无效\", \"UPSTREAM_INVALID_RESPONSE\");\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const name = row.hashtag_name.replace(/^#/, \"\").trim();\n        if (!name) return Result.Err(\"TikTok 话题名称为空\", \"UPSTREAM_INVALID_RESPONSE\");\n        entries.push({ id: \"tiktok:hashtag:\" + id.data, title: \"#\" + name, link: \"https://www.tiktok.com/tag/\" + encodeURIComponent(name),\n          rank: row.rank_position == null || row.rank_position === \"\" ? null : Number(row.rank_position), pinned: false,\n          heat: { value: row.posts ?? null, unit: \"周期内投稿\", text: String(row.posts ?? \"\") } });\n      }\n      return Result.Ok({ category, title: \"TikTok · \" + country + \" · \" + days + \" 天热门话题\", link: \"https://ads.tiktok.com/creative/creativeCenter/trends?region=\" + country, entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new TiktokHotRank();\nexport const route = {\n  name: \"TikTok · 热门话题\", path: \"/tiktok/hot/:country?/:days?\", url: \"www.tiktok.com\",\n  maintainers: [\"findrss\"], example: \"/tiktok/hot/US/7\", parameters: { country: \"US（默认）、JP、GB 等官方支持地区\", days: \"1、7（默认）、30、120\" },\n  description: \"官方 TikTok Business Discovery 热门话题榜，需广告账户和获批的 Discovery API 令牌；保留 rank_position 与周期内投稿数，未知为 null。非个性化 For You 推荐流。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_75 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"综合\";\nexport const order = 470;\n// Favicon: https://sf3-cdn-tos.douyinstatic.com/obj/eden-cn/uhbfnupkbps/toutiao_favicon.ico\nexport const platform = {\n  name: \"今日头条\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"toutiao-hot-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"toutiao-hot-favicon\\\"/></svg>\",\n};\nimport { utils } from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"toutiao\",\n  \"name\": \"今日头条\",\n  \"home\": \"https://www.toutiao.com\"\n};\nexport class ToutiaoHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const request_options = {};\n      request_options.headers = {\n        Referer: source.home,\n        ...request_options.headers\n      };\n      const fetched = await utils.request_json(ctx, \"https://www.toutiao.com/hot-event/hot-board/?origin=toutiao_pc\", request_options);\n      if (fetched.error) return fetched;\n      const data = fetched.data;\n      if (!data || typeof data !== 'object') return Result.Err('上游未返回数据对象', 'UPSTREAM_INVALID_RESPONSE');\n      if (data.need_force_login) return Result.Err('上游要求登录，请更新并授权 Cookie', 'UPSTREAM_AUTH_REQUIRED');\n      if (data.error || data.errors?.length || (typeof data.code === 'number' && data.code < 0) || (data.error_code !== undefined && data.error_code !== 0)) return Result.Err('上游拒绝请求，请检查账户权限或验证页面', 'UPSTREAM_INVALID_RESPONSE');\n      const list = utils.array_at(data, \"data\");\n      if (list.error) return list;\n      const rows = list.data;\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        const id = utils.identity(row.ClusterIdStr);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url('https://www.toutiao.com/trending/' + encodeURIComponent(id.data) + '/', source.home);\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = row.rank;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String(row.HotValue ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.Title),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n}\nconst script = new ToutiaoHotRank();\nexport const route = {\n  \"name\": \"今日头条\",\n  \"path\": \"/toutiao/hot\",\n  \"url\": \"www.toutiao.com\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/toutiao/hot\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_76 = "/** HOT */\nexport const version = \"1.0.1\";\nexport const category = \"社区\";\nexport const order = 480;\n// Favicon: https://v2ex.com/static/icon-192.png\nexport const platform = {\n  name: \"V2EX\",\n  icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"v2ex-share-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"v2ex-share-favicon\\\"/></svg>\",\n};\nimport { utils } from '@findrss/util';\n/*\nAdapted from https://github.com/newsnext/newsnow/tree/0f95b2c998dffbfd2ddbc51b47b5809887dc6b97/server/sources\nMIT License\n\nCopyright (c) 2024 ourongxing\n\nPermission is hereby granted, free of charge, to any person obtaining a copy\nof this software and associated documentation files (the \"Software\"), to deal\nin the Software without restriction, including without limitation the rights\nto use, copy, modify, merge, publish, distribute, sublicense, and/or sell\ncopies of the Software, and to permit persons to whom the Software is\nfurnished to do so, subject to the following conditions:\n\nThe above copyright notice and this permission notice shall be included in all\ncopies or substantial portions of the Software.\n\nTHE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR\nIMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,\nFITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE\nAUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER\nLIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,\nOUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE\nSOFTWARE.\n\n*/\nconst source = {\n  \"id\": \"v2ex-share\",\n  \"name\": \"V2EX · 最新分享\",\n  \"home\": \"https://v2ex.com/\"\n};\nexport class V2exShareHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const rows = [];\n      for (const channel of [\"create\", \"ideas\", \"programmer\", \"share\"]) {\n        const fetched = await utils.request_json(ctx, 'https://www.v2ex.com/feed/' + channel + '.json', {\n          headers: {\n            Referer: source.home\n          }\n        });\n        if (fetched.error) return fetched;\n        const list = utils.array_at(fetched.data, \"items\");\n        if (list.error) return list;\n        rows.push(...list.data);\n      }\n      const entries = [],\n        seen = new Set();\n      for (const row of rows) {\n        const id = utils.identity(row.id);\n        if (id.error) return id;\n        if (seen.has(id.data)) continue;\n        seen.add(id.data);\n        const link = utils.absolute_url(row.url, source.home);\n        if (link.error) return link;\n        const pinned = false;\n        const raw_rank = null;\n        const rank = pinned ? null : raw_rank === undefined || raw_rank === null || raw_rank === '' ? null : Number(raw_rank);\n        const heat_text = String('' ?? '').trim();\n        const heat_number = heat_text === '' ? NaN : Number(heat_text.replace(/,/g, ''));\n        entries.push({\n          id: source.id + ':' + id.data,\n          title: utils.plain_text(row.title),\n          link: link.data,\n          rank,\n          pinned,\n          heat: {\n            value: Number.isFinite(heat_number) && heat_number >= 0 ? heat_number : null,\n            unit: \"热度\",\n            text: heat_text\n          }\n        });\n      }\n      ctx.log('榜单解析完成', {\n        source: source.id,\n        count: entries.length,\n        missing_rank: entries.filter(entry => entry.rank === null && !entry.pinned).length\n      });\n      return Result.Ok({\n        title: source.name,\n        category,\n        link: source.home,\n        entries\n      });\n    } catch (error) {\n      return Result.Err(error, error?.code ?? 'UPSTREAM_INVALID_RESPONSE');\n    }\n  }\n}\nconst script = new V2exShareHotRank();\nexport const route = {\n  \"name\": \"V2EX · 最新分享\",\n  \"path\": \"/v2ex/share\",\n  \"url\": \"v2ex.com\",\n  \"maintainers\": [\"findrss\"],\n  \"example\": \"/v2ex/share\",\n  \"parameters\": {},\n  \"description\": \"列表快照 JSON，保留上游顺序、已提供的排名与热度；未知排名和热度为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
const source_77 = "/** HOT */\nimport { utils } from \"@findrss/util\";\n\nexport const version = \"1.0.0\";\nexport const category = \"视频\";\nexport const order = 740;\n// Favicon: https://www.google.com/s2/favicons?domain=vimeo.com&sz=32\nexport const platform = { name: \"Vimeo\", icon: \"<svg xmlns=\\\"http://www.w3.org/2000/svg\\\" width=\\\"32\\\" height=\\\"32\\\" viewBox=\\\"0 0 32 32\\\" data-n=\\\"vimeo-platform-icon\\\"><image width=\\\"32\\\" height=\\\"32\\\" href=\\\"data:image/png;base64,\\\" data-n=\\\"vimeo-favicon\\\"/></svg>\" };\nexport const tags = [\"视频\",\"英语\"];\n\nexport class VimeoHotRank extends HotRankScript {\n  async fetch(ctx) {\n    try {\n      const fetched = await utils.request_text(ctx, \"https://vimeo.com/channels/staffpicks/videos/rss\");\n      if (fetched.error) return fetched;\n      const list = utils.feed_items(fetched.data, \"https://vimeo.com/channels/staffpicks\");\n      if (list.error) return list;\n      if (!list.data.length) return Result.Err(\"Vimeo 未返回内容列表\", \"UPSTREAM_INVALID_RESPONSE\");\n      const entries = [], seen = new Set();\n      for (const row of list.data) {\n        if (seen.has(row.id)) continue;\n        seen.add(row.id);\n        entries.push({ id: \"vimeo:\" + row.id, title: utils.plain_text(row.title), link: row.link,\n          rank: null, pinned: false, heat: { value: null, unit: \"热度\", text: \"\" } });\n      }\n      return Result.Ok({ category, title: \"Vimeo · Staff Picks 精选\", link: \"https://vimeo.com/channels/staffpicks\", entries });\n    } catch (error) { return Result.Err(error, error?.code ?? \"UPSTREAM_INVALID_RESPONSE\"); }\n  }\n}\n\nconst script = new VimeoHotRank();\nexport const route = {\n  name: \"Vimeo · Staff Picks 精选\", path: \"/vimeo/staff-picks\", url: \"vimeo.com\",\n  maintainers: [\"findrss\"], example: \"/vimeo/staff-picks\", parameters: {},\n  description: \"官方 RSS/Atom 内容列表，保留上游选择和顺序。新闻及精选列表不冒充热度排名，未知排名与热度均为 null。\",\n  handler: ctx => script.run(ctx),\n};\n";
